// Glues CsrTrigger and StateDrain. The simulator's run-loop calls on_retire
// once per committed PC; the controller decides via the trigger map whether
// to drain state and returns the populated hybrid_state_v1 if so. The
// caller (simulator.hpp) is responsible for writing the file and exiting
// with EXIT_HANDOFF_TO_QEMU.

#pragma once

#include "hybrid/csr_trigger.hpp"
#include "hybrid/insn_match.h"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "hybrid/state_drain.hpp"

#include <cstdint>
#include <optional>
#include <utility>

namespace hybrid
{

template<typename Trigger>
class HandoffController
{
public:
  // scratch_gpa (L26): forwarded to StateDrain for the V dump sweep; defaults
  // to the unset sentinel (non-V drains never read it). The simulator passes
  // the real mmap-top-page GPA. caps: the target core's Andes-CSR support,
  // forwarded to StateDrain so the drain re-read skips CSRs the core lacks.
  HandoffController(Trigger trigger, DmiBus& bus,
                    uint64_t scratch_gpa = kVScratchGpaUnset,
                    AndesCaps caps = AndesCaps::all())
      : trigger_{std::move(trigger)}, drain_{bus, scratch_gpa, caps}
  {}

  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
  // a per-field DM Abstract Command on every handoff.
  void set_passthrough_input(hybrid_state_v1 input)
  {
    passthrough_ = input;
  }

  // #1: when enabled, an EXIT drains only mcycle/minstret (StateDrain::
  // drain_counters_only) and passes every other field through from the
  // passthrough snapshot, instead of reading back the full register file. The
  // driver turns this on whenever --verify is off, where only the vsim mcycle
  // delta is consumed -- so the ~190 full-drain abstract commands are wasted.
  void set_minimal_drain(bool on)
  {
    minimal_drain_ = on;
  }

  // v5: forward the engine's L2C presence + MMIO base to the exit drain, so it
  // re-reads the writable L2C config registers for --verify (dual of the resume
  // side's set_l2c). Off unless the engine has an L2C.
  void set_l2c(bool present, uint64_t base) { drain_.set_l2c(present, base); }

  // Read-only view of the underlying trigger. Used by the ROI kanata-gate
  // derivation, which needs to read scanned EXIT PCs without consuming them.
  auto trigger() const -> const Trigger& { return trigger_; }

  auto on_retire(uint64_t pc) -> std::optional<hybrid_state_v1>
  {
    if constexpr (requires { trigger_.observe_commit(); }) {
      trigger_.observe_commit();
    }
    const auto hit = trigger_.lookup(pc);
    // Only EXIT drains; entry is QEMU's job, vsim ignores ENTER.
    if (!hit || hit->kind != HYBRID_HANDOFF_EXIT)
      return std::nullopt;
    if (passthrough_)
      return minimal_drain_ ? drain_.drain_counters_only(*passthrough_)
                            : drain_.drain_with_passthrough(*passthrough_);
    return drain_.drain();
  }

private:
  Trigger trigger_;
  StateDrain drain_;
  std::optional<hybrid_state_v1> passthrough_;
  bool minimal_drain_ = false;
};

}  // namespace hybrid

#pragma once

namespace hybrid
{

// Returned by Simulator::run() when the vsim->QEMU drain has fired.
inline constexpr int kExitHandoffToQemu = 200;

}  // namespace hybrid

// HandoffController glues CsrTrigger and StateDrain. Given a retired PC,
// decides whether to drain state and returns the populated hybrid_state_v1
// if so. Pure-logic; no SystemC.

#include "hybrid/abstract_command.hpp"
#include "hybrid/csr_trigger.hpp"
#include "hybrid/handoff_controller.hpp"
#include "hybrid/insn_match.h"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "insn_encoders.hpp"
#include "recording_bus.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <array>
#include <cstdint>

using hybrid::test::as_bytes;
using hybrid::test::encode_slti;
using hybrid::test::kDmstatusHaltedAndAcked;
using hybrid::test::RecordingBus;
using RD = hybrid::ResumeDriver;

TEST_CASE("HandoffController: EXIT marker triggers drain and returns state")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_gpr(12)] = 3;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000004;

  hybrid::CsrTrigger trigger;
  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A1)};
  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000000);

  REQUIRE(state);
  CHECK(state->magic == HYBRID_STATE_MAGIC);
  CHECK(state->gpr[12] == 3);
  CHECK(state->pc == 0x80000004);
}

TEST_CASE("HandoffController: non-trigger PC returns nullopt without drain")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::CsrTrigger trigger;
  hybrid::HandoffController h(std::move(trigger), bus);

  const auto state = h.on_retire(0xDEADBEEF);
  CHECK_FALSE(state.has_value());
  CHECK(bus.ops.empty());
}

TEST_CASE("HandoffController: ENTER marker never fires (vsim ignores entry)")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::CsrTrigger trigger;
  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A0)};
  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000000);
  CHECK_FALSE(state.has_value());
  CHECK(bus.ops.empty());
}

TEST_CASE("HandoffController: PC-mode synthetic EXIT hit drains like marker EXIT")
{
  // PC-trigger mode populates the trigger map via add_pc_hit() instead of
  // scan_buffer(). HandoffController must dispatch on `kind` only and not
  // depend on a recorded `insn`. This is the single-test contract the PC
  // mode relies on.
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_gpr(12)] = 7;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000048;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000044);

  REQUIRE(state);
  CHECK(state->magic == HYBRID_STATE_MAGIC);
  CHECK(state->gpr[12] == 7);
  CHECK(state->pc == 0x80000048);
}

TEST_CASE("HandoffController: PC-mode hit at unrelated PC stays silent")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000048);
  CHECK_FALSE(state.has_value());
  CHECK(bus.ops.empty());
}

// GPR/FPR transport is Abstract-Command-only: a full EXIT drain reads
// x1..x31 and f0..f31 one abstract read each, and never issues a PB sd/fsd
// sweep -- even under the simulator's production drain configuration.
TEST_CASE("HandoffController: full EXIT drain reads GPRs/FPRs via abstract "
          "commands, never a PB block-store sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize=8
  for (uint16_t i = 1; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0xAB00ULL + i;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xFB00ULL + i;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.vlenb   = 64;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus, /*scratch_gpa=*/0x88000000);
  h.set_passthrough_input(input);

  const auto state = h.on_retire(0x80000044);
  REQUIRE(state.has_value());

  // Every GPR/FPR value arrives via its abstract read...
  for (int i = 1; i < 32; ++i)
    CHECK(state->gpr[i] == 0xAB00ULL + uint64_t(i));
  for (int i = 0; i < 32; ++i)
    CHECK(state->fpr[i] == 0xFB00ULL + uint64_t(i));
  // ...and no Program-Buffer execution occurred at all (no V state, no L2C).
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == hybrid::test::DmiOp::Kind::Write
                 && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

// CSR transport is Abstract-Command-only on the drain side too (the legacy PB
// csrr+sd sweep was removed): a full EXIT drain reads every caps-supported
// Andes+M-ext CSR with its own abstract read, directly into the drained state.
TEST_CASE("HandoffController: full EXIT drain reads Andes+M-ext CSRs via "
          "abstract commands, never a PB csrr+sd sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize=8

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  input.vlenb   = 0;

  // Preload the regfile so every transported CSR has a distinct value.
  std::vector<uint16_t> addrs;
  hybrid::for_each_transport_csr(input, hybrid::AndesCaps::all(),
    [&](uint16_t addr, const uint64_t&) { addrs.push_back(addr); });
  REQUIRE(!addrs.empty());
  for (std::size_t k = 0; k < addrs.size(); ++k)
    bus.regfile[hybrid::regno_csr(addrs[k])] = 0xC5000000ULL + k;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus, /*scratch_gpa=*/0x88000000);
  h.set_passthrough_input(input);

  const auto state = h.on_retire(0x80000044);
  REQUIRE(state.has_value());

  // Every transported CSR's value landed via its own abstract read...
  std::size_t k = 0;
  hybrid::for_each_transport_csr(*state, hybrid::AndesCaps::all(),
    [&](uint16_t, const uint64_t& field) {
      CHECK(field == 0xC5000000ULL + k);
      ++k;
    });
  // ...and no Program-Buffer execution occurred at all (no V state, no L2C).
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == hybrid::test::DmiOp::Kind::Write
                 && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

// #1: set_minimal_drain(true) makes an EXIT route to StateDrain's counters-only
// path -- refresh mcycle/minstret, pass everything else through from the QEMU1
// snapshot, and issue just two abstract reads instead of the full ~190.
TEST_CASE("HandoffController: minimal-drain routes EXIT to counters-only drain")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrMcycle)]   = 0x111;
  bus.regfile[hybrid::regno_csr(RD::kCsrMinstret)] = 0x222;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
  input.gpr[12] = 0xABC;  // distinctive: must pass through, never re-read

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus);
  h.set_passthrough_input(input);
  h.set_minimal_drain(true);

  const auto state = h.on_retire(0x80000044);
  REQUIRE(state);
  CHECK(state->mcycle   == 0x111);
  CHECK(state->minstret == 0x222);
  CHECK(state->gpr[12]  == 0xABC);  // passthrough; a full drain would read 0 here

  int reads = 0;
  for (const auto& op : bus.ops)
    if (op.kind == hybrid::test::DmiOp::Kind::Write && op.reg == RD::kCommand
        && ((op.value >> 16) & 1u) == 0u)
      ++reads;
  CHECK(reads == 2);
}

1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	
12	#include <cstdint>
13	
14	namespace hybrid
15	{
16	
17	class StateDrain
18	{
19	public:
20	  using RD = ResumeDriver;
21	
22	  explicit StateDrain(DmiBus& bus) : bus_{bus} {}
23	
24	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
25	  // drain_with_passthrough when the QEMU 1 snapshot is available.
26	  auto drain() -> hybrid_state_v1
27	  {
28	    hybrid_state_v1 state{};
29	    state.magic   = HYBRID_STATE_MAGIC;
30	    state.version = HYBRID_STATE_VERSION;
31	    state.flags   = HYBRID_FLAG_RV64;
32	    halt_and_capture_pc_priv(state);
33	
34	    for (uint16_t i = 1; i < 32; ++i)
35	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
36	
37	    return state;
38	  }
39	
40	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
41	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
42	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
43	  // QEMU 1 snapshot leaks into the drained state).
44	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
45	  // contribution would otherwise be discarded as the passthrough preserves
46	  // QEMU1's pre-handoff value.
47	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
48	  {
49	    auto state = input;
50	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
51	
52	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
53	    // like the resume side -- the Program Buffer is reserved for state the
54	    // abstract command space cannot reach.
55	    for (uint16_t i = 1; i < 32; ++i)
56	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
57	
58	    if (input.flags & HYBRID_FLAG_FP) {
59	      for (uint16_t i = 0; i < 32; ++i)
60	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
61	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
62	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
63	    }
64	
65	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
66	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
67	    // dropped and the stale QEMU1 value passes through into the drained state.
68	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
69	
70	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
71	    // restores them), so re-read them -- an in-ROI write must reach the drained
72	    // state instead of the stale QEMU1 passthrough value.
73	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
74	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
75	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
76	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
77	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
78	
79	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
80	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
81	
82	    return state;
83	  }
84	
85	private:
86	  // Halt the hart and capture the two control fields every drain path needs:
87	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
88	  // blocks are filled by the caller, so drain() and drain_with_passthrough
89	  // share one halt + prologue. dmactive must transition 0->1 in its own write
90	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
91	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
92	  {
93	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
94	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
95	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
96	                   "StateDrain halt");
97	
98	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
99	                                  "StateDrain DCSR") & 0x3u;
100	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
101	  }
102	
103	  DmiBus& bus_;
104	};
